<script>document.addEventListener('DOMContentLoaded',()=>{const f=document.getElementById('loginForm');if(!f)return;f.addEventListener('submit',e=>{const u=document.getElementById('cedula');const p=document.getElementById('password');const ok=/^(?:[0-9]{7,8}|123Admin)$/.test(u.value.trim())&&p.value.length>=6;u.classList.toggle('is-invalid',!(/^(?:[0-9]{7,8}|123Admin)$/.test(u.value.trim())));p.classList.toggle('is-invalid',p.value.length<6);if(!ok)e.preventDefault();});});</script>
